if (UnityEditor.EditorApplication.isPlayingOrWillChangePlaymode) throw new System.InvalidOperationException("Stop Play before verification setup.");
var scene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
if (scene.isDirty) throw new System.InvalidOperationException("Unsaved scene must be preserved.");
UnityEditor.SessionState.SetString("PLAN018.OriginalScene", scene.path);
UnityEditor.SessionState.SetString("PLAN018.OriginalStart", UnityEditor.AssetDatabase.GetAssetPath(UnityEditor.SceneManagement.EditorSceneManager.playModeStartScene));
foreach (var key in new[]{"Continue","SlotB"}) { UnityEditor.SessionState.SetBool("PLAN018.Has"+key,UnityEditor.EditorPrefs.HasKey("MobileGame.AppPlayEntry."+key)); UnityEditor.SessionState.SetBool("PLAN018."+key,UnityEditor.EditorPrefs.GetBool("MobileGame.AppPlayEntry."+key)); }
var slot = System.IO.Path.Combine(UnityEngine.Application.temporaryCachePath,"EditorSessions","SlotB","session.json");
var language = System.IO.Path.Combine(UnityEngine.Application.temporaryCachePath,"Preferences","language.json");
var paths = new[]{slot,MobileGame.Persistence.UiSettingsStore.PathForGameSave(slot),language};
for(int i=0;i<paths.Length;i++) { UnityEditor.SessionState.SetString("PLAN018.Path"+i,paths[i]); UnityEditor.SessionState.SetString("PLAN018.Bytes"+i,System.IO.File.Exists(paths[i])?System.Convert.ToBase64String(System.IO.File.ReadAllBytes(paths[i])):"MISSING"); }
UnityEditor.SessionState.SetBool("PLAN018.Background",UnityEngine.Application.runInBackground);
return new { originalScene=scene.path, filesBackedUp=paths.Length };
